lh_wstr_ptr
lh_wstr_raw_to_lower(lh_wstr_ptr str, lh_usize_t n)
{
    lh_runtime_check_ref(str);
    lh_wstr_ptr p = str;

    while (n--)
    {
        lh_wchar_t c = lh_ptr_deref(p);

        lh_wchar_case_pair_t r;
        lh_bool_t is_founded = lh_bool_false;

        lh_interval_ropen_binary_search(lh_usize_t, m_wchar_to_lower_table,
                                        m_wchar_to_lower_table_size, c, first, r, is_founded);

        *p++ = is_founded ? r.second : c;
    }

    return p;
}

